/**
 * Homepage hero photo: one definition read by BOTH src/components/HomeHero.tsx
 * (the <picture>) and vite.config.ts (the <link rel="preload"> it adds to "/"
 * only). A preload whose imagesrcset/imagesizes differ from the <img> fetches
 * one candidate and renders another, so the two must come from here.
 *
 * Dependency-free on purpose: vite.config.ts imports it, and the config cannot
 * load siteData (which reads the __BUILD_YEAR__ define).
 *
 * Variants are generated by scripts/gen-images.mjs from
 * scripts/image-src/IMG_2034.JPEG (metadata stripped).
 */
export const HERO_IMAGE_BASE =
  "/images/godhans-crew-spider-lift-skid-steer-stump-grinder-jacksonville-nc";

export const HERO_IMAGE_WIDTHS = [768, 1024, 1280, 1920] as const;

/** Intrinsic size of the largest variant (the master is 4:3). */
export const HERO_IMAGE_WIDTH = 1920;
export const HERO_IMAGE_HEIGHT = 1440;

export const heroSrcset = (ext: "avif" | "webp") =>
  HERO_IMAGE_WIDTHS.map((w) => `${HERO_IMAGE_BASE}-${w}.${ext} ${w}w`).join(", ");

/**
 * The photo box is 100vw wide and 45vh / 55vh / 65vh tall (phone / tablet /
 * desktop — see .home-hero-media in index.css). With object-fit: cover on a
 * 4:3 image the rendered width is the larger of the box width and its height
 * × 4/3, so a phone's image is height-bound at 60vh.
 */
export const HERO_IMAGE_SIZES =
  "(min-width: 1024px) max(100vw, 86.67vh), (min-width: 768px) max(100vw, 73.33vh), max(100vw, 60vh)";
